CREATE FUNCTION cmd_validate_spacecraft_leg_start_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE e journey_leg_execution%ROWTYPE; BEGIN SELECT * INTO STRICT e FROM journey_leg_execution WHERE journey_leg_id=NEW.journey_leg_id; IF e.start_command_id<>NEW.command_id OR e.campaign_id<>NEW.campaign_id OR e.ship_id<>NEW.ship_id OR e.duration_seconds<>NEW.duration_seconds OR e.departure_day<>NEW.departure_day OR e.departure_second<>NEW.departure_second THEN RAISE EXCEPTION 'Spacecraft leg start receipt does not match execution'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_spacecraft_leg_start_valid AFTER INSERT ON cmd_spacecraft_leg_start_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_spacecraft_leg_start_receipt();
CREATE FUNCTION cmd_validate_spacecraft_leg_complete_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE e journey_leg_execution%ROWTYPE; BEGIN SELECT * INTO STRICT e FROM journey_leg_execution WHERE journey_leg_id=NEW.journey_leg_id; IF e.complete_command_id<>NEW.command_id OR e.campaign_id<>NEW.campaign_id OR e.ship_id<>NEW.ship_id OR e.arrival_day<>NEW.clock_day_after OR e.arrival_second<>NEW.clock_second_after THEN RAISE EXCEPTION 'Spacecraft leg completion receipt does not match execution'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_spacecraft_leg_complete_valid AFTER INSERT ON cmd_spacecraft_leg_complete_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_spacecraft_leg_complete_receipt();
